// ============================================================================
// RGMII_apb: APB4 register wrapper around RGMII_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/RGMII.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/RGMII.md
// ============================================================================
module RGMII_apb #(
  parameter int DEPTH = 16
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic tx_clk,
  output logic [3:0] txd,
  output logic tx_ctl,
  input logic rx_clk,
  input logic [3:0] rxd,
  input logic rx_ctl
);
  localparam logic [31:0] ID_VALUE = 32'h52470200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [22:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd23) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & (~|hit | (PWRITE & (PSTRB != 4'hF) & (hit[6])));   // core registers take whole words

  // ---------------- core ----------------
  logic          c_wen;
  logic [7:0]    c_wdata;
  logic          c_ren;
  logic [7:0]    c_rdata;
  logic [4:0]    c_count;
  logic          c_irq;
  RGMII_top #(.DEPTH(DEPTH)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .tx_clk(tx_clk),
    .txd(txd),
    .tx_ctl(tx_ctl),
    .rx_clk(rx_clk),
    .rxd(rxd),
    .rx_ctl(rx_ctl),
    .wen(c_wen),
    .waddr((wr ? ((hit[6] ? 4'd0 : 4'd0)) : 4'd0)),
    .wdata(c_wdata),
    .ren(c_ren),
    .raddr((rd ? ((hit[7] ? 4'd0 : 4'd0) | (hit[8] ? 4'd1 : 4'd0) | (hit[9] ? 4'd2 : 4'd0) | (hit[10] ? 4'd3 : 4'd0) | (hit[11] ? 4'd4 : 4'd0) | (hit[12] ? 4'd5 : 4'd0) | (hit[13] ? 4'd6 : 4'd0) | (hit[14] ? 4'd7 : 4'd0) | (hit[15] ? 4'd8 : 4'd0) | (hit[16] ? 4'd9 : 4'd0) | (hit[17] ? 4'd10 : 4'd0) | (hit[18] ? 4'd11 : 4'd0) | (hit[19] ? 4'd12 : 4'd0) | (hit[20] ? 4'd13 : 4'd0) | (hit[21] ? 4'd14 : 4'd0) | (hit[22] ? 4'd15 : 4'd0)) : 4'd0)),
    .rdata(c_rdata),
    .count(c_count),
    .irq(c_irq)
  );

  // ---------------- registers ----------------
  logic [0:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[0:0] & wmask[0:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[0:0]) | (PWDATA[0:0] & wmask[0:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
    end
  end

  // ---------------- core inputs ----------------
  // CORE: the core's register port (indices on the instance)
  assign c_wen = wr & (PSTRB == 4'hF) & (hit[6]);
  assign c_wdata = PWDATA[7:0];
  assign c_ren = rd & (hit[7] | hit[8] | hit[9] | hit[10] | hit[11] | hit[12] | hit[13] | hit[14] | hit[15] | hit[16] | hit[17] | hit[18] | hit[19] | hit[20] | hit[21] | hit[22]);

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_irq;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] rdata;
  always_comb begin
    rdata = '0;
    case (PADDR[11:2])
      10'd0: rdata = ID_VALUE;
      10'd1: rdata = 32'(irq_status);
      10'd2: rdata = 32'(irq_enable);
      10'd4: rdata = scratch;
      10'd5: rdata = 32'({c_count});
      10'd7: rdata = 32'(c_rdata);
      10'd8: rdata = 32'(c_rdata);
      10'd9: rdata = 32'(c_rdata);
      10'd10: rdata = 32'(c_rdata);
      10'd11: rdata = 32'(c_rdata);
      10'd12: rdata = 32'(c_rdata);
      10'd13: rdata = 32'(c_rdata);
      10'd14: rdata = 32'(c_rdata);
      10'd15: rdata = 32'(c_rdata);
      10'd16: rdata = 32'(c_rdata);
      10'd17: rdata = 32'(c_rdata);
      10'd18: rdata = 32'(c_rdata);
      10'd19: rdata = 32'(c_rdata);
      10'd20: rdata = 32'(c_rdata);
      10'd21: rdata = 32'(c_rdata);
      10'd22: rdata = 32'(c_rdata);
      default: rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? rdata : '0;
endmodule
